// VALIDATE SCOUT SETUP
// Stops the run before either Notion query and before the email when
// configuration is missing or out of range.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

// Deliberately conservative: enough to catch an empty or obviously malformed
// value before Gmail is asked to send.
const recipient = (cfg.recipientEmail || '').toString().trim();
if (!recipient) {
  problems.push('recipientEmail is empty. Set the address that should receive the scorecard.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@.]{2,}$/.test(recipient)) {
  problems.push('recipientEmail does not look like an email address.');
}

const REQUIRED_TARGETS = ['newSignals', 'tier2Plus', 'replies', 'scanOrDemo'];
const targets = (cfg.weeklyTargets && typeof cfg.weeklyTargets === 'object') ? cfg.weeklyTargets : null;

if (!targets) {
  problems.push('weeklyTargets must be an object of weekly goals.');
} else {
  for (const key of REQUIRED_TARGETS) {
    const value = Number(targets[key]);
    if (!Number.isInteger(value) || value < 0 || value > 1000) {
      problems.push('weeklyTargets.' + key + ' must be a whole number from 0 to 1000.');
    }
  }
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

return [{ json: { validated: true } }];

// COMPUTE THE WEEKLY SCORECARD
// Reads the two Notion queries and builds one HTML email comparing the week
// against the targets in Scout Setup. A completely quiet week still produces a
// scorecard: an empty board is a result, not a failure.
const cfg = $('Scout Setup').first().json;
const targets = cfg.weeklyTargets || {};
const nowMs = +$now;
const weekStart = new Date(nowMs - 7 * 86400000).toISOString().slice(0, 10);
const weekEnd = new Date(nowMs).toISOString().slice(0, 10);

// Parses an absolute http(s) URL without the `URL` global, which n8n's Code
// node sandbox does not provide. Returns null for anything it will not vouch
// for, so every caller can treat null as "refuse this value".
function parseHttpUrl(value) {
  const raw = (value === null || value === undefined ? '' : String(value)).trim();
  if (!raw) return null;

  // No spaces, tabs, newlines or control characters anywhere. A URL carrying
  // one is either malformed or an attempt to hide a second value inside the
  // first, and neither is worth guessing about.
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i);
    if (code <= 0x20 || code === 0x7f) return null;
  }

  // Backslashes are rejected rather than normalised. Browsers treat a
  // backslash as "/", so an authority written with one can read as a hostile
  // host in a browser and a trusted host in a naive parser. Scout refuses the
  // ambiguity instead of picking a side.
  if (raw.indexOf('\\') !== -1) return null;

  const parts = /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#[\s\S]*)?$/.exec(raw);
  if (!parts) return null;

  const protocol = parts[1].toLowerCase() + ':';
  if (protocol !== 'http:' && protocol !== 'https:') return null;

  const authority = parts[2];
  if (!authority) return null;

  // Split user information off the authority. Scout never sends credentials in
  // a URL, but workflow 01 has to be able to see that someone tried.
  let username = '';
  let password = '';
  let hostport = authority;
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    const userinfo = authority.slice(0, at);
    if (!userinfo) return null;
    hostport = authority.slice(at + 1);
    const sep = userinfo.indexOf(':');
    username = sep === -1 ? userinfo : userinfo.slice(0, sep);
    password = sep === -1 ? '' : userinfo.slice(sep + 1);
  }
  if (!hostport) return null;

  // Separate an optional port so it can never be mistaken for part of the host.
  let hostname = hostport;
  let port = '';
  if (hostport.charAt(0) === '[') {
    const close = hostport.indexOf(']');
    if (close === -1) return null;
    hostname = hostport.slice(0, close + 1);
    const rest = hostport.slice(close + 1);
    if (rest) {
      if (rest.charAt(0) !== ':') return null;
      port = rest.slice(1);
    }
  } else {
    const sep = hostport.indexOf(':');
    if (sep !== -1) {
      hostname = hostport.slice(0, sep);
      port = hostport.slice(sep + 1);
    }
    // Only ASCII hosts are accepted. An internationalised name would need
    // punycode conversion to compare safely, and Scout has no need of one.
    if (!/^[A-Za-z0-9._~%-]+$/.test(hostname)) return null;
  }
  if (!hostname) return null;
  if (port && !/^[0-9]+$/.test(port)) return null;

  const pathname = parts[3] || '/';
  const search = parts[4] || '';
  const hash = parts[5] || '';
  const host = port ? hostname + ':' + port : hostname;
  const href = protocol + '//' + host + pathname + search + hash;

  return {
    protocol: protocol,
    username: username,
    password: password,
    hostname: hostname,
    port: port,
    host: host,
    pathname: pathname,
    search: search,
    hash: hash,
    href: href,
    toString: function () { return href; }
  };
}

// Everything interpolated into the email below is user-controlled data that
// arrived from Notion, so it is escaped before it reaches the HTML.
function escapeHtml(value) {
  return (value === null || value === undefined ? '' : String(value))
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Only http(s) links become anchors. Anything else is rendered as plain text
// so a hostile value cannot smuggle a script URL into the operator's inbox.
function safeHref(value) {
  const parsed = parseHttpUrl(value);
  if (!parsed) return '';
  return escapeHtml(parsed.href);
}

function props(page) { return (page && page.properties) || {}; }
function sel(page, key) { const v = props(page)[key]; return (v && v.select && v.select.name) || ''; }
function checkbox(page, key) { const v = props(page)[key]; return !!(v && v.checkbox); }
function urlOf(page, key) { const v = props(page)[key]; return (v && v.url) || ''; }
function titleOf(page) {
  const t = (props(page).Name && props(page).Name.title) || [];
  return t.map((x) => x.plain_text || '').join('') || '(untitled)';
}

function resultsOf(nodeName) {
  try {
    const payload = $(nodeName).first().json;
    return Array.isArray(payload.results) ? payload.results : [];
  } catch (e) {
    return [];
  }
}

const created = resultsOf('Query New This Week');
const touched = resultsOf('Query Touched This Week');

function tally(pages, key) {
  const counts = {};
  for (const page of pages) {
    const value = sel(page, key) || 'Unknown';
    counts[value] = (counts[value] || 0) + 1;
  }
  return counts;
}

function tallyRows(counts) {
  const keys = Object.keys(counts).sort((a, b) => counts[b] - counts[a]);
  if (keys.length === 0) return '<tr><td colspan="2" style="color:#888">none</td></tr>';
  return keys
    .map((k) => '<tr><td>' + escapeHtml(k) + '</td><td style="text-align:right"><b>' + counts[k] + '</b></td></tr>')
    .join('');
}

const newCount = created.length;
const tiers = tally(created, 'Warmth tier');
const tier1 = tiers['Tier 1 (hot)'] || 0;
const tier2 = tiers['Tier 2 (warm)'] || 0;
const tier2Plus = tier1 + tier2;
const replies = touched.filter((p) => checkbox(p, 'Replied')).length;
const inConversation = touched.filter((p) => sel(p, 'Status') === 'In conversation').length;
const scanOrDemo = touched.filter((p) => sel(p, 'Status') === 'Scan/Demo').length;
const dms = created.filter((p) => sel(p, 'Next action') === 'DM').length;
const connects = created.filter((p) => sel(p, 'Next action') === 'Connect').length;

const quietWeek = newCount === 0 && touched.length === 0;

function scoreRow(label, actual, target) {
  const goal = Number(target);
  const safeGoal = Number.isInteger(goal) ? goal : 0;
  return '<tr><td>' + escapeHtml(label) + '</td>' +
    '<td style="text-align:right"><b>' + actual + '</b></td>' +
    '<td style="text-align:right;color:#888">' + safeGoal + '</td>' +
    '<td style="text-align:center">' + (actual >= safeGoal ? 'hit' : '&mdash;') + '</td></tr>';
}

const hotRows = created.filter((p) => sel(p, 'Warmth tier') === 'Tier 1 (hot)').slice(0, 8);
const hotList = hotRows.length === 0
  ? '<li style="color:#888">none this week</li>'
  : hotRows.map((p) => {
      const href = safeHref(urlOf(p, 'Source URL'));
      const label = escapeHtml(titleOf(p));
      return '<li>' + (href ? '<a href="' + href + '">' + label + '</a>' : label) + '</li>';
    }).join('');

const header = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;color:#222">' +
  '<h2 style="margin-bottom:4px">Scout weekly scorecard</h2>' +
  '<div style="color:#888;margin-bottom:16px">' + escapeHtml(weekStart) + ' to ' + escapeHtml(weekEnd) + '</div>';

// A quiet week is reported plainly rather than as a wall of empty tables.
const body = quietWeek
  ? '<div>No new signals and no activity on existing rows this week.</div>' +
    '<div style="color:#888;margin-top:8px">Targets were ' + escapeHtml(Number(targets.newSignals) || 0) +
    ' new signals and ' + escapeHtml(Number(targets.tier2Plus) || 0) + ' at Tier 2 or better.</div>'
  : '<table style="border-collapse:collapse;width:100%;margin-bottom:20px" cellpadding="6">' +
    '<tr style="border-bottom:2px solid #eee;color:#888;text-align:left">' +
    '<th>Metric</th><th style="text-align:right">Actual</th><th style="text-align:right">Target</th><th></th></tr>' +
    scoreRow('New signals', newCount, targets.newSignals) +
    scoreRow('Tier 2 or better', tier2Plus, targets.tier2Plus) +
    scoreRow('Replies', replies, targets.replies) +
    scoreRow('Scan or demo', scanOrDemo, targets.scanOrDemo) +
    '</table>' +
    '<table style="border-collapse:collapse;width:48%;display:inline-table;vertical-align:top;margin-right:3%" cellpadding="5">' +
    '<tr style="border-bottom:1px solid #eee;color:#888;text-align:left"><th>By source</th><th></th></tr>' +
    tallyRows(tally(created, 'Source')) + '</table>' +
    '<table style="border-collapse:collapse;width:48%;display:inline-table;vertical-align:top" cellpadding="5">' +
    '<tr style="border-bottom:1px solid #eee;color:#888;text-align:left"><th>By track</th><th></th></tr>' +
    tallyRows(tally(created, 'Track')) + '</table>' +
    '<table style="border-collapse:collapse;width:48%;display:inline-table;vertical-align:top;margin-right:3%;margin-top:14px" cellpadding="5">' +
    '<tr style="border-bottom:1px solid #eee;color:#888;text-align:left"><th>By persona</th><th></th></tr>' +
    tallyRows(tally(created, 'Persona type')) + '</table>' +
    '<table style="border-collapse:collapse;width:48%;display:inline-table;vertical-align:top;margin-top:14px" cellpadding="5">' +
    '<tr style="border-bottom:1px solid #eee;color:#888;text-align:left"><th>Pipeline now</th><th></th></tr>' +
    '<tr><td>In conversation</td><td style="text-align:right"><b>' + inConversation + '</b></td></tr>' +
    '<tr><td>Marked DM</td><td style="text-align:right"><b>' + dms + '</b></td></tr>' +
    '<tr><td>Marked Connect</td><td style="text-align:right"><b>' + connects + '</b></td></tr>' +
    '</table>' +
    '<h3 style="margin-top:24px;margin-bottom:6px">Tier 1 signals this week</h3>' +
    '<ul style="margin-top:0">' + hotList + '</ul>';

const footer = '<div style="color:#aaa;font-size:12px;margin-top:20px">' +
  'Counted from your Notion signal map. Comments posted and messages sent are not tracked here, ' +
  'because Scout does not send them.</div></div>';

const subject = quietWeek
  ? 'Scout scorecard, week of ' + weekStart + ': no activity'
  : 'Scout scorecard, week of ' + weekStart + ': ' + newCount + ' new, ' + tier2Plus + ' Tier 2+';

return [{ json: {
  subject,
  html: header + body + footer,
  quietWeek,
  newCount,
  tier1,
  tier2,
  tier2Plus,
  replies,
  scanOrDemo,
  inConversation
} }];
